INSERT INTO stock
    (
          stock_code
        , stock_name
        , market
        , close_price
        , change_price
        , change_rate
        , open_price
        , high_price
        , low_price
        , volume
        , trading_value
        , market_cap
        , listed_shares
    )
VALUES
    (
          #{stock_code}
        , #{stock_name}
        , #{market}
        , #{close_price}
        , #{change_price}
        , #{change_rate}
        , #{open_price}
        , #{high_price}
        , #{low_price}
        , #{volume}
        , #{trading_value}
        , #{market_cap}
        , #{listed_shares}
    )

mapper.update:
UPDATE stock
SET
      stock_name = #{stock_name}
    , market =  #{market}
    , close_price =  #{close_price}
    , change_price =  #{change_price}
    , change_rate =  #{change_rate}
    , open_price =  #{open_price}
    , high_price =  #{high_price}
    , low_price =  #{low_price}
    , volume =  #{volume}
    , trading_value =  #{trading_value}
    , market_cap =  #{market_cap}
    , listed_shares = #{listed_shares}
WHERE    1=1
    AND  stock_code = #{stock_code}
